@Component("orderItem-handler")
@ProcessingGroup("orderItem-processing-group")
public class OrderItemEventHandler {
	
	// core constructor
	OrderItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOrderItemEvent
     */
    @EventHandler
    public void handle( CreateOrderItemEvent event) {
        entityManager.persist(new OrderItem(event.getOrderItemId(), event.getQuantity(), event.getUnitPrice(), event.getDiscountAmount(), event.getTaxAmount(), event.getTotalAmount(), event.getOrder(), event.getProduct(), event.getPriceBookEntry()));
    }

    /*
     * @param	event UpdateOrderItemEvent
     */
    @EventHandler
    public OrderItem handle( UpdateOrderItemEvent event) {
    	entityManager.merge(new OrderItem(event.getOrderItemId(), event.getQuantity(), event.getUnitPrice(), event.getDiscountAmount(), event.getTaxAmount(), event.getTotalAmount(), event.getOrder(), event.getProduct(), event.getPriceBookEntry()));
    }
    
    /*
     * @param	event DeleteOrderItemEvent
     */
    @EventHandler
    public void on( DeleteOrderItemEvent event) {
    	OrderItem entity = new OrderItem();
   
    	// ------------------------------------------
    	// apply the OrderItemId
    	// ------------------------------------------
    	entity.setOrderItemId( event.getOrderItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OrderItemRepository orderItemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OrderItemEventHandler.class.getName());

}
